// ── Target ────────────────────────────────────────────────────────────────────

// What a target is: from a checked blueprint, and buf's set when the source is a `.proto`, the files
// one language's output holds, each under the header beadc writes above it (decision 0022). The
// header leads the file, as `@generated` markers do: protoplugin prints its imports above anything a
// plugin prints, and its preamble, the one place above them, takes a `.proto` file a blueprint alone
// has none of and turns the lint off, so beadc writes the header above protoplugin's output.

// dependencies

import type { IBlueprint } from '../model/blueprint.ts';
import { beadcVersion, PROTOBUF_FLOOR, protocGenEsVersion } from '../version.ts';

// types

/** A file a target writes: its path under the output's folder, with slashes, and its text. */
export interface IGeneratedFile {
  readonly name: string;
  readonly content: string;
}

/**
 * What a header names as a file's source: the blueprint's path, or each `.proto` file's, by its
 * import path; each as `beadc.yaml`'s folder sees it, with slashes.
 */
export type SourceNames =
  | { readonly blueprint: string }
  | { readonly proto: ReadonlyMap<string, string> };

/** What a target generates from. */
export interface ITargetInput {
  readonly blueprint: IBlueprint;
  /** buf's set, a FileDescriptorSet, for a `.proto` source. */
  readonly set?: Uint8Array;
  readonly sources: SourceNames;
}

/** A target: one language's files, from a checked blueprint. */
export interface ITarget<Options> {
  readonly name: string;
  readonly generate: (input: ITargetInput, options: Options) => readonly IGeneratedFile[];
}

// definition

/** The source a header names for a service declared in `protoFile`, or in the blueprint alone. */
export const sourceNameOf = (sources: SourceNames, protoFile: string | undefined): string => {
  if ('blueprint' in sources) {
    return sources.blueprint;
  }

  return (protoFile === undefined ? undefined : sources.proto.get(protoFile)) ?? protoFile ?? '';
};

/**
 * The header beadc writes above a file it generates, then a blank line: beadc's version, the source,
 * the format and the spec's version; and, where its messages are generated, protoc-gen-es's version
 * and the oldest `@bufbuild/protobuf` its output runs on. `tools/release.mjs` reads its first line.
 */
export const headerOf = (
  blueprint: IBlueprint,
  details: { readonly source: string; readonly messages?: boolean }
): string => {
  const lines = [
    `// @generated by beadc ${beadcVersion()} from ${details.source}: ${blueprint.format}, spec ${blueprint.specVersion}.`,
    '// Do not edit: regenerate with beadc.',
    ...(details.messages === true
      ? [
          `// Messages: protoc-gen-es ${protocGenEsVersion()}, for @bufbuild/protobuf ${PROTOBUF_FLOOR} or later.`,
        ]
      : []),
  ];

  return `${lines.join('\n')}\n\n`;
};
